-- Table: appearance_settings
DROP TABLE IF EXISTS [appearance_settings];
CREATE TABLE "appearance_settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime);


-- Table: cache
DROP TABLE IF EXISTS [cache];
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));


-- Table: cache_locks
DROP TABLE IF EXISTS [cache_locks];
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));


-- Table: commissions
DROP TABLE IF EXISTS [commissions];
CREATE TABLE "commissions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "order_id" integer not null, "source_user_id" integer not null, "order_amount" numeric not null, "commission_rate" numeric not null, "commission_amount" numeric not null, "level" integer not null default '1', "status" varchar check ("status" in ('pending', 'paid', 'cancelled')) not null default 'pending', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("order_id") references "orders"("id") on delete cascade, foreign key("source_user_id") references "users"("id") on delete cascade);


-- Table: failed_jobs
DROP TABLE IF EXISTS [failed_jobs];
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);


-- Table: job_batches
DROP TABLE IF EXISTS [job_batches];
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));


-- Table: jobs
DROP TABLE IF EXISTS [jobs];
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);


-- Table: migrations
DROP TABLE IF EXISTS [migrations];
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);


-- Table: order_items
DROP TABLE IF EXISTS [order_items];
CREATE TABLE "order_items" ("id" integer primary key autoincrement not null, "order_id" integer not null, "product_id" integer not null, "product_variant_id" integer, "product_title" varchar not null, "variant_name" varchar, "unit_price" numeric not null, "quantity" integer not null, "line_total" numeric not null, foreign key("order_id") references "orders"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete restrict, foreign key("product_variant_id") references "product_variants"("id") on delete set null);


-- Table: orders
DROP TABLE IF EXISTS [orders];
CREATE TABLE "orders" ("id" integer primary key autoincrement not null, "order_number" varchar not null, "user_id" integer, "customer_info" text not null, "subtotal" numeric not null, "discount_percent" numeric not null default '0', "discount_amount" numeric not null default '0', "shipping_cost" numeric not null default '0', "total" numeric not null, "status" varchar check ("status" in ('pending_payment', 'processing', 'shipped', 'completed', 'rejected')) not null default 'pending_payment', "created_at" datetime, "updated_at" datetime, "tracking_number" varchar, "shipping_provider" varchar, foreign key("user_id") references "users"("id") on delete set null);


-- Table: password_reset_tokens
DROP TABLE IF EXISTS [password_reset_tokens];
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));


-- Table: payment_proofs
DROP TABLE IF EXISTS [payment_proofs];
CREATE TABLE "payment_proofs" ("id" integer primary key autoincrement not null, "order_id" integer not null, "file_path" varchar not null, "admin_notes" text, "status" varchar check ("status" in ('pending', 'approved', 'rejected')) not null default 'pending', "reviewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade);


-- Table: personal_access_tokens
DROP TABLE IF EXISTS [personal_access_tokens];
CREATE TABLE "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);


-- Table: product_media
DROP TABLE IF EXISTS [product_media];
CREATE TABLE "product_media" ("id" integer primary key autoincrement not null, "product_id" integer not null, "file_path" varchar not null, "type" varchar check ("type" in ('image', 'video')) not null default 'image', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);


-- Table: product_variants
DROP TABLE IF EXISTS [product_variants];
CREATE TABLE "product_variants" ("id" integer primary key autoincrement not null, "product_id" integer not null, "name" varchar not null, "price" numeric not null, "created_at" datetime, "updated_at" datetime, "stock" integer, foreign key("product_id") references "products"("id") on delete cascade);


-- Table: products
DROP TABLE IF EXISTS [products];
CREATE TABLE "products" ("id" integer primary key autoincrement not null, "title" varchar not null, "price" numeric not null, "original_price" numeric, "discount_label" varchar, "category" varchar not null default 'Uncategorized', "description" text, "main_image" varchar, "is_promo" tinyint(1) not null default '0', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, "stock" integer, "deleted_at" datetime);


-- Table: sessions
DROP TABLE IF EXISTS [sessions];
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));


-- Table: starcenter_applications
DROP TABLE IF EXISTS [starcenter_applications];
CREATE TABLE "starcenter_applications" ("id" integer primary key autoincrement not null, "center_name" varchar not null, "full_name" varchar not null, "birth_date" date not null, "birth_place" varchar not null, "gender" varchar check ("gender" in ('L', 'P')) not null, "religion" varchar not null, "marital_status" varchar not null, "occupation" varchar not null, "id_card_path" varchar not null, "email" varchar not null, "phone" varchar not null, "shop_link" varchar, "bank_name" varchar not null, "bank_number" varchar not null, "bank_account_name" varchar not null, "bank_book_path" varchar not null, "tax_number" varchar, "tax_doc_path" varchar, "referral_code" varchar, "referrer_id" integer, "status" varchar check ("status" in ('pending', 'approved', 'rejected')) not null default 'pending', "reject_reason" text, "user_id" integer, "created_at" datetime, "updated_at" datetime, "nik" varchar, foreign key("referrer_id") references "users"("id") on delete set null, foreign key("user_id") references "users"("id") on delete set null);


-- Table: starcenter_network
DROP TABLE IF EXISTS [starcenter_network];
CREATE TABLE "starcenter_network" ("id" integer primary key autoincrement not null, "upline_id" integer not null, "downline_id" integer not null, "depth" integer not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("upline_id") references "users"("id") on delete cascade, foreign key("downline_id") references "users"("id") on delete cascade);


-- Table: system_settings
DROP TABLE IF EXISTS [system_settings];
CREATE TABLE "system_settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "group" varchar not null default 'general', "created_at" datetime, "updated_at" datetime);


-- Table: tiers
DROP TABLE IF EXISTS [tiers];
CREATE TABLE "tiers" ("id" integer primary key autoincrement not null, "slug" varchar not null, "name" varchar not null, "min_spend" numeric not null default '0', "discount_percent" numeric not null default '0', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);


-- Table: users
DROP TABLE IF EXISTS [users];
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "phone" varchar, "address" text, "city" varchar, "postal_code" varchar, "role" varchar check ("role" in ('regular', 'starcenter', 'admin')) not null default 'regular', "tier_id" integer, "referrer_id" integer, "referral_code" varchar, "cumulative_spending" numeric not null default '0', "last_transaction_at" datetime, foreign key("tier_id") references "tiers"("id") on delete set null, foreign key("referrer_id") references "users"("id") on delete set null);


CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "tiers_slug_unique" on "tiers" ("slug");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "users_referral_code_unique" on "users" ("referral_code");
CREATE UNIQUE INDEX "orders_order_number_unique" on "orders" ("order_number");
CREATE UNIQUE INDEX "starcenter_network_upline_id_downline_id_unique" on "starcenter_network" ("upline_id", "downline_id");
CREATE UNIQUE INDEX "system_settings_key_unique" on "system_settings" ("key");
CREATE UNIQUE INDEX "appearance_settings_key_unique" on "appearance_settings" ("key");
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE INDEX "personal_access_tokens_expires_at_index" on "personal_access_tokens" ("expires_at");
CREATE INDEX "idx_users_referrer_id" on "users" ("referrer_id");
CREATE INDEX "idx_users_referral_code" on "users" ("referral_code");
CREATE INDEX "idx_orders_user_status" on "orders" ("user_id", "status");
CREATE INDEX "idx_orders_order_number" on "orders" ("order_number");
CREATE INDEX "idx_commissions_user_status" on "commissions" ("user_id", "status");
CREATE INDEX "idx_network_downline_depth" on "starcenter_network" ("downline_id", "depth");
CREATE INDEX "idx_network_upline_depth" on "starcenter_network" ("upline_id", "depth");
CREATE UNIQUE INDEX "starcenter_applications_center_name_unique" on "starcenter_applications" ("center_name");
CREATE UNIQUE INDEX "starcenter_applications_email_unique" on "starcenter_applications" ("email");
